with kept_keys as (select city from suppliers intersect all select city from suppliers where supplier_name like '%Tokyo%'), verified as (select s.* from suppliers s join kept_keys k on s.city = k.city) select city, rating, case when city rlike '^(London|Tokyo)$' then 'CORE' when city rlike '^(Bangkok|Chiang Mai)$' then 'EXTENDED' else 'GROUP_A' end as city_zone from verified order by city_zone;
